package shortener

import (
	"context"
	"crypto/hmac"
	"crypto/sha256"
	"encoding/binary"
	"sync"
)

const (
	alphabet = "0123456789abcdefghijklmnopqrstuvwxyzABCDEFGHIJKLMNOPQRSTUVWXYZ"
	codeLen  = 7
	space    = uint64(3521614606208) // 62^7
	halfBits = 21                     // 42-bit Feistel domain covers the space (2^42 > 62^7)
	halfMask = (1 << halfBits) - 1
)

// RangeStore hands out disjoint ID ranges, e.g. UPDATE counters SET next = next + $size RETURNING next - $size.
type RangeStore interface {
	Lease(ctx context.Context, size uint64) (start uint64, err error)
}

type Generator struct {
	mu        sync.Mutex
	store     RangeStore
	key       []byte
	size      uint64
	next, end uint64
}

func NewGenerator(store RangeStore, key []byte, rangeSize uint64) *Generator {
	return &Generator{store: store, key: key, size: rangeSize}
}

// Next returns a unique, non-sequential 7-character code.
func (g *Generator) Next(ctx context.Context) (string, error) {
	g.mu.Lock()
	defer g.mu.Unlock()
	if g.next == g.end { // production code prefetches the next lease in the background at ~80% use
		start, err := g.store.Lease(ctx, g.size)
		if err != nil {
			return "", err
		}
		g.next, g.end = start, start+g.size
	}
	id := g.next
	g.next++
	if id >= space {
		panic("id space exhausted") // decades away at 100M codes/day; alert long before
	}
	return encode(g.permute(id)), nil
}

func (g *Generator) round(r uint64, i byte) uint64 {
	mac := hmac.New(sha256.New, g.key)
	var buf [9]byte
	binary.BigEndian.PutUint64(buf[:8], r)
	buf[8] = i
	mac.Write(buf[:])
	return binary.BigEndian.Uint64(mac.Sum(nil)[:8]) & halfMask
}

// permute is a keyed bijection on [0, 62^7): a 4-round Feistel network on 42 bits plus cycle walking.
// A Feistel network is invertible for any round function, so distinct ids always give distinct codes.
func (g *Generator) permute(id uint64) uint64 {
	x := id
	for {
		l, r := x>>halfBits, x&halfMask
		for i := byte(0); i < 4; i++ {
			l, r = r, l^g.round(r, i)
		}
		x = l<<halfBits | r
		if x < space { // outputs above 62^7 are walked again; the walk always returns into range
			return x
		}
	}
}

func encode(n uint64) string {
	var out [codeLen]byte
	for i := codeLen - 1; i >= 0; i-- {
		out[i] = alphabet[n%62]
		n /= 62
	}
	return string(out[:])
}

// Custom aliases: a conditional insert is the uniqueness check, so two concurrent requests cannot both win.
import { z } from "zod";

const createSchema = z.object({
  url: z.string().url().max(2048).refine((u) => /^https?:\/\//i.test(u), "Only http(s) URLs"),
  // Generated codes are exactly 7 chars, so aliases of 8+ chars can never collide with them.
  alias: z.string().regex(/^[A-Za-z0-9-]{8,32}$/).optional(),
  expiresAt: z.coerce.date().optional(),
});

interface LinkStore {
  // Resolves false when the code already exists (DynamoDB: attribute_not_exists(code); SQL: ON CONFLICT DO NOTHING).
  putIfAbsent(link: { code: string; longUrl: string; ownerId: string; expiresAt?: Date }): Promise<boolean>;
}
interface Deps {
  store: LinkStore;
  nextCode: () => Promise<string>; // the range-allocating generator
  isUnsafe: (url: string) => Promise<boolean>; // threat-list lookup
  cacheWarm: (code: string, url: string) => Promise<void>;
}

const RESERVED = new Set(["api", "admin", "login", "static", "health"]);

export async function createLink(deps: Deps, ownerId: string, input: unknown) {
  const { url, alias, expiresAt } = createSchema.parse(input);
  if (await deps.isUnsafe(url)) return { status: 400 as const, error: "unsafe url" };

  if (alias) {
    if (RESERVED.has(alias.toLowerCase())) return { status: 409 as const, error: "alias reserved" };
    const ok = await deps.store.putIfAbsent({ code: alias, longUrl: url, ownerId, expiresAt });
    if (!ok) return { status: 409 as const, error: "alias taken" };
    await deps.cacheWarm(alias, url);
    return { status: 201 as const, code: alias };
  }

  // Generated codes are unique by construction; putIfAbsent still guards against a misconfigured range store.
  for (let attempt = 0; attempt < 3; attempt++) {
    const code = await deps.nextCode();
    if (await deps.store.putIfAbsent({ code, longUrl: url, ownerId, expiresAt })) {
      await deps.cacheWarm(code, url);
      return { status: 201 as const, code };
    }
  }
  throw new Error("could not allocate a code");
}

package fanout

import (
	"context"
	"fmt"
	"time"

	"github.com/redis/go-redis/v9"
)

const (
	timelineCap        = 800
	celebrityThreshold = 100_000
	chunkSize          = 1_000
)

// Redis scores are float64 (53-bit mantissa), so a raw 64-bit Snowflake id would lose precision.
// Score by the id's 41-bit millisecond timestamp; the member keeps the exact id and breaks ties.
func score(postID int64) float64 { return float64(postID >> 22) }

type Graph interface {
	FollowerCount(ctx context.Context, authorID int64) (int64, error)
	// Followers pages through followers active in the last `since`; returns the next page token ("" at end).
	Followers(ctx context.Context, authorID int64, since time.Duration, page string, n int) ([]int64, string, error)
}

type Worker struct {
	rdb   *redis.ClusterClient
	graph Graph
}

// HandlePostCreated is called by a Kafka consumer for each post.created event (at-least-once delivery).
func (w *Worker) HandlePostCreated(ctx context.Context, authorID, postID int64) error {
	n, err := w.graph.FollowerCount(ctx, authorID)
	if err != nil {
		return err
	}
	if n >= celebrityThreshold {
		// Pull model: readers merge this author's recent posts at read time.
		return w.rdb.ZAdd(ctx, fmt.Sprintf("recent:%d", authorID), redis.Z{Score: score(postID), Member: postID}).Err()
	}
	page := ""
	for {
		ids, next, err := w.graph.Followers(ctx, authorID, 30*24*time.Hour, page, chunkSize)
		if err != nil {
			return err // the consumer retries; ZADD below makes re-delivery harmless
		}
		pipe := w.rdb.Pipeline()
		for _, f := range ids {
			key := fmt.Sprintf("timeline:%d", f)
			pipe.ZAdd(ctx, key, redis.Z{Score: score(postID), Member: postID}) // idempotent on retry
			pipe.ZRemRangeByRank(ctx, key, 0, -timelineCap-1)                    // keep newest 800
		}
		if _, err := pipe.Exec(ctx); err != nil {
			return err
		}
		if next == "" {
			return nil
		}
		page = next
	}
}

// Read path: merge pushed timeline + pulled celebrity posts, filter, paginate by cursor, hydrate in batches.
// Post ids are time-ordered 64-bit (Snowflake-style), so bigint comparison = time order.
type PostId = bigint;
interface Post { id: PostId; authorId: string; text: string; deleted: boolean }
interface Author { id: string; name: string; avatarUrl: string }

interface Deps {
  timeline(userId: string, olderThan: PostId | null, n: number): Promise<PostId[]>; // Redis, newest first
  celebritiesFollowed(userId: string): Promise<string[]>;
  recentPosts(authorId: string, olderThan: PostId | null, n: number): Promise<PostId[]>; // hot cache
  hiddenAuthors(userId: string): Promise<Set<string>>; // blocked + muted + unfollowed
  getPosts(ids: PostId[]): Promise<Map<PostId, Post>>; // one multi-get
  getAuthors(ids: string[]): Promise<Map<string, Author>>; // one multi-get
}

/** Max-heap over the heads of k sorted (descending) lists: O(n log k) merge. */
function* mergeDesc(lists: PostId[][]): Generator<PostId> {
  const heap: { id: PostId; list: number; idx: number }[] = [];
  const up = (i: number) => {
    while (i > 0) {
      const p = (i - 1) >> 1;
      if (heap[p].id >= heap[i].id) return;
      [heap[p], heap[i]] = [heap[i], heap[p]];
      i = p;
    }
  };
  const down = (i: number) => {
    for (;;) {
      const l = 2 * i + 1, r = l + 1;
      let m = i;
      if (l < heap.length && heap[l].id > heap[m].id) m = l;
      if (r < heap.length && heap[r].id > heap[m].id) m = r;
      if (m === i) return;
      [heap[m], heap[i]] = [heap[i], heap[m]];
      i = m;
    }
  };
  lists.forEach((l, list) => { if (l.length) { heap.push({ id: l[0], list, idx: 0 }); up(heap.length - 1); } });
  while (heap.length) {
    const top = heap[0];
    yield top.id;
    const next = lists[top.list][top.idx + 1];
    if (next !== undefined) {
      heap[0] = { id: next, list: top.list, idx: top.idx + 1 };
    } else {
      heap[0] = heap[heap.length - 1];
      heap.pop();
    }
    if (heap.length) down(0);
  }
}

export async function assembleFeed(deps: Deps, userId: string, cursor: PostId | null, pageSize = 20) {
  const fetchN = pageSize * 2; // over-fetch so filtering rarely leaves a short page
  const [pushed, celebs, hidden] = await Promise.all([
    deps.timeline(userId, cursor, fetchN),
    deps.celebritiesFollowed(userId),
    deps.hiddenAuthors(userId),
  ]);
  // A slow celebrity cache must not fail the feed: drop that source instead.
  const pulled = await Promise.all(celebs.map((a) => deps.recentPosts(a, cursor, fetchN).catch(() => [] as PostId[])));

  const candidates: PostId[] = [];
  let last: PostId | null = null;
  for (const id of mergeDesc([pushed, ...pulled])) {
    if (id === last) continue; // dedupe: same id from two sources or a retried fan-out
    last = id;
    candidates.push(id);
    if (candidates.length >= fetchN) break;
  }

  const posts = await deps.getPosts(candidates);
  const visible = candidates
    .map((id) => posts.get(id))
    .filter((p): p is Post => !!p && !p.deleted && !hidden.has(p.authorId))
    .slice(0, pageSize);
  const authors = await deps.getAuthors([...new Set(visible.map((p) => p.authorId))]);

  return {
    items: visible.map((p) => ({ post: { id: p.id.toString(), text: p.text }, author: authors.get(p.authorId) ?? null })),
    nextCursor: visible.length ? visible[visible.length - 1].id.toString() : null,
  };
}

package chat

import (
	"context"
	"errors"
	"log/slog"
	"time"
)

type Message struct {
	ConversationID int64
	Seq            int64
	MsgID          int64
	SenderID       int64
	ClientMsgID    string
	Body           []byte
	CreatedAt      time.Time
}

type DeviceConn struct {
	UserID, DeviceID string
	GatewayID        string
}

type Store interface {
	IsMember(ctx context.Context, conv, user int64) (bool, error)
	Members(ctx context.Context, conv int64) ([]int64, error)
	// NextSeq atomically increments the conversation's counter (INCR or conditional update).
	NextSeq(ctx context.Context, conv int64) (int64, error)
	// FindByClientID returns the stored message for a retried send, if any (fast path, avoids burning a seq).
	FindByClientID(ctx context.Context, conv int64, clientMsgID string) (Message, bool, error)
	// InsertUnique fails with ErrDuplicate if (conversation, clientMsgID) exists, returning the stored message.
	InsertUnique(ctx context.Context, m Message) (Message, error)
}
type Registry interface {
	Devices(ctx context.Context, userIDs []int64) ([]DeviceConn, []int64, error) // online conns, users with offline devices
}
type GatewayBus interface {
	Publish(ctx context.Context, gatewayID string, deviceID string, m Message) error
}
type PushQueue interface{ Enqueue(ctx context.Context, userID int64, m Message) error }
type IDGen interface{ Next() int64 }

var ErrDuplicate = errors.New("duplicate client message")
var ErrForbidden = errors.New("not a member")

type Service struct {
	store Store
	reg   Registry
	bus   GatewayBus
	push  PushQueue
	ids   IDGen
}

// HandleSend persists first, then acks, then fans out asynchronously. Returns the ordered message for the "sent" frame.
func (s *Service) HandleSend(ctx context.Context, sender int64, conv int64, clientMsgID string, body []byte) (Message, error) {
	ok, err := s.store.IsMember(ctx, conv, sender)
	if err != nil {
		return Message{}, err
	}
	if !ok {
		return Message{}, ErrForbidden
	}
	if prev, found, err := s.store.FindByClientID(ctx, conv, clientMsgID); err != nil {
		return Message{}, err
	} else if found {
		return prev, nil // retry after a lost "sent" frame: same seq, no second fan-out
	}
	seq, err := s.store.NextSeq(ctx, conv)
	if err != nil {
		return Message{}, err
	}
	m := Message{ConversationID: conv, Seq: seq, MsgID: s.ids.Next(), SenderID: sender,
		ClientMsgID: clientMsgID, Body: body, CreatedAt: time.Now().UTC()}
	stored, err := s.store.InsertUnique(ctx, m)
	if errors.Is(err, ErrDuplicate) {
		// Lost a race with a concurrent retry. The seq we allocated is burned; range fetches report
		// completeThrough so clients skip it instead of waiting for it forever.
		return stored, nil
	}
	if err != nil {
		return Message{}, err // client retries with the same clientMsgID
	}
	// Fan-out is detached from the request; an outbox-driven job can replay it after a crash.
	go s.fanOut(context.WithoutCancel(ctx), stored)
	return stored, nil
}

func (s *Service) fanOut(ctx context.Context, m Message) {
	ctx, cancel := context.WithTimeout(ctx, 5*time.Second)
	defer cancel()
	members, err := s.store.Members(ctx, m.ConversationID)
	if err != nil {
		slog.Warn("fanout members", "conv", m.ConversationID, "err", err)
		return // recipients still get it via sync
	}
	// Includes the sender: their other devices must show the message too.
	online, offlineUsers, err := s.reg.Devices(ctx, members)
	if err != nil {
		slog.Warn("fanout registry", "conv", m.ConversationID, "err", err)
		return
	}
	for _, d := range online {
		if err := s.bus.Publish(ctx, d.GatewayID, d.DeviceID, m); err != nil {
			slog.Debug("gateway publish failed, device will sync", "gateway", d.GatewayID)
		}
	}
	for _, u := range offlineUsers {
		if u != m.SenderID {
			_ = s.push.Enqueue(ctx, u, m) // push service applies mute settings and collapses bursts
		}
	}
}

// Client side: idempotent apply, gap detection, batched cumulative acks.
interface IncomingMessage { conversationId: string; seq: number; from: string; body: string }

interface Transport {
  send(frame: object): void;
  // completeThrough: the server vouches nothing else exists up to this seq (covers seqs burned by deduped retries).
  fetchRange(conversationId: string, fromSeq: number, toSeq: number): Promise<{ messages: IncomingMessage[]; completeThrough: number }>;
}

export class ConversationReceiver {
  private messages = new Map<number, IncomingMessage>(); // seq -> message; a real app persists to IndexedDB/SQLite
  private contiguous: number; // every seq <= contiguous is present
  private ackTimer: ReturnType<typeof setTimeout> | null = null;
  private fetching = false;

  constructor(private readonly conversationId: string, private readonly transport: Transport, lastSyncedSeq: number) {
    this.contiguous = lastSyncedSeq;
  }

  /** Called for pushed messages and for sync results alike; duplicates are ignored. */
  async apply(m: IncomingMessage): Promise<void> {
    if (m.seq <= this.contiguous || this.messages.has(m.seq)) return; // duplicate (push + sync overlap)
    this.messages.set(m.seq, m);
    this.advance();
    if (m.seq > this.contiguous + 1) await this.fillGap(m.seq - 1);
  }

  private advance(): void {
    const before = this.contiguous;
    while (this.messages.has(this.contiguous + 1)) this.contiguous++;
    if (this.contiguous > before) this.scheduleAck();
  }

  private async fillGap(upTo: number): Promise<void> {
    if (this.fetching) return; // one gap fetch at a time; later arrivals re-check after it finishes
    this.fetching = true;
    try {
      const { messages, completeThrough } = await this.transport.fetchRange(this.conversationId, this.contiguous + 1, upTo);
      for (const m of messages) if (!this.messages.has(m.seq)) this.messages.set(m.seq, m);
      this.contiguous = Math.max(this.contiguous, completeThrough);
      this.advance();
      this.scheduleAck();
    } finally {
      this.fetching = false;
    }
  }

  private scheduleAck(): void {
    if (this.ackTimer) return;
    this.ackTimer = setTimeout(() => {
      this.ackTimer = null;
      // Cumulative: one frame acknowledges everything up to contiguous.
      this.transport.send({ type: "ack", conversationId: this.conversationId, upToSeq: this.contiguous });
    }, 300);
  }

  visible(): IncomingMessage[] {
    return [...this.messages.values()].sort((a, b) => a.seq - b.seq);
  }
}
